<!doctype html><html><head><meta name="robots" content="noindex,nofollow"><meta charset="utf-8"><title>Health &amp; Safety Healthcheck Report</title><?php wp_head(); ?></head><body><main class="acorn-hc"><h1>Health &amp; Safety Healthcheck Report</h1><p><strong><?php echo esc_html($report['meta']['company']); ?></strong> · Self-assessment report</p><h2>Executive summary</h2><ul><li><?php echo (int)$report['summary']['priority_count']; ?> Priority actions</li><li><?php echo (int)$report['summary']['review_count']; ?> Areas to review</li><li><?php echo (int)$report['summary']['addressed_count']; ?> Areas where no obvious gap was identified</li></ul><?php foreach(['addressed','review','priority'] as$type):?><section><h2><?php echo esc_html($report['sections'][$type]['label']); ?></h2><?php foreach($report[$type]as$item):?><article><h3><?php echo esc_html($item['question_text']); ?></h3><p><?php echo esc_html($item['positive_text']??'Review the recommendation and next steps.'); ?></p></article><?php endforeach;?></section><?php endforeach;?><p><?php echo esc_html($report['disclaimer']); ?></p><section><h2><?php echo esc_html($report['support']['heading']); ?></h2><a href="<?php echo esc_url($report['support']['cta_url']); ?>"><?php echo esc_html($report['support']['cta_label']); ?></a></section></main><?php wp_footer();?></body></html>
